alter table if exists mall_order add column if not exists remark varchar(500) not null default '';
alter table if exists mall_order add column if not exists payment_expired_at timestamptz;
alter table if exists mall_order add column if not exists shipping_company varchar(64);
alter table if exists mall_order add column if not exists tracking_no varchar(100);
create table if not exists order_freight_rule (id bigint generated by default as identity primary key, region varchar(80) not null, base_amount numeric(18,2) not null default 0, free_threshold numeric(18,2) not null default 0, enabled boolean not null default true);
create table if not exists order_after_sale (id bigint generated by default as identity primary key, order_id bigint not null references mall_order(id) on delete restrict, user_id bigint not null references sys_user(id) on delete cascade, type varchar(30) not null, amount numeric(18,2) not null, reason varchar(500) not null, status varchar(20) not null default 'Applied', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index if not exists ix_after_sale_order_status on order_after_sale(order_id, status);
create table if not exists order_logistics_trace (id bigint generated by default as identity primary key, order_id bigint not null unique references mall_order(id) on delete cascade, company varchar(64) not null, tracking_no varchar(100) not null, status varchar(30) not null default 'CREATED', trace_json jsonb not null default '[]', updated_at timestamptz not null default now());
create table if not exists order_review (id bigint generated by default as identity primary key, order_id bigint not null references mall_order(id) on delete restrict, user_id bigint not null references sys_user(id) on delete cascade, rating integer not null, content varchar(1000) not null default '', anonymous boolean not null default false, created_at timestamptz not null default now(), unique(order_id, user_id), constraint ck_order_review_rating check (rating between 1 and 5));
